/**
 * @canvas      Welcome — a single "Hello" artboard with one heading · dark studio
 * @ds          maude
 * @platform    desktop
 * @artboards   hello
 */

import "../system/maude/colors_and_type.css";
import { DesignCanvas, DCSection, DCArtboard } from "@maude/canvas-lib";

export default function Welcome() {
  return (
    <DesignCanvas>
      <DCSection id="welcome" title="Welcome">
        <DCArtboard id="hello" label="Hello" width={800} height={500}>
          <div
            className="maude"
            data-theme="dark"
            style={{
              position: "absolute",
              inset: 0,
              display: "grid",
              placeItems: "center",
              background: "var(--bg-0)",
            }}
          >
            <h1
              style={{
                margin: 0,
                fontFamily: "var(--font-display)",
                fontSize: 64,
                fontWeight: 600,
                color: "var(--fg-0)",
              }}
            >
              Hello
            </h1>
          </div>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

